    if(symbolType==='ground'){const keep=oldPins[0],k={id:c.connectors?.[0]?.id||uid('conn'),name:'接地端',side:'top',pins:[keep||pin(1,'GND','接地')]};k.pins[0].no='1';k.pins[0].definition='GND';k.pins[0].function=k.pins[0].function||'接地';c.connectors=[k];return;}
