  function metaField(k,label,type='text'){return`<label><span>${label}</span><input data-meta="${k}" type="${type}" value="${esc(state.meta[k])}"></label>`;}
  function typeOptions(selected,data){return Object.entries(data).map(([k,v])=>`<option value="${k}"${k===selected?' selected':''}>${esc(v.name||v)}</option>`).join('');}
  function componentTypeOptions(selected){return[['component','内部部件'],['external-hv','外部高压连接器'],['external-lv','外部低压连接器'],['container','分区边界']].map(([k,v])=>`<option value="${k}"${k===selected?' selected':''}>${v}</option>`).join('');}
  function connectorHtml(c,k){const locked=c.type==='device'&&c.symbolType==='ground';return`<details class="sch-connector" data-connector-id="${k.id}"${k.open===false?'':' open'}><summary><b>${esc(k.name)}</b><span>${k.pins.length} Pin · ${locked?'顶部固定':esc(k.side)}</span></summary><div class="sch-connector-fields"><input data-connector-field="name" value="${esc(k.name)}" aria-label="连接器名称"><select data-connector-field="side"${locked?' disabled':''}><option value="left"${k.side==='left'?' selected':''}>左侧</option><option value="right"${k.side==='right'?' selected':''}>右侧</option><option value="top"${k.side==='top'?' selected':''}>上侧</option><option value="bottom"${k.side==='bottom'?' selected':''}>下侧</option></select><label>Pin数<input data-pin-count type="number" min="1" max="96" value="${k.pins.length}"${locked?' disabled':''}></label><button class="btn danger" data-delete-connector="${k.id}"${locked?' disabled':''}>删除连接器</button></div><div class="sch-paste-hint">${locked?'接地器件固定为顶部单Pin输入端，可编辑Pin定义和功能。':'可从 Excel 粘贴：Pin号　定义　功能（每列以制表符分隔）'}</div><div class="sch-pin-table"><div class="sch-pin-head"><b>Pin号</b><b>定义</b><b>功能（可空）</b></div>${k.pins.map(p=>`<div class="sch-pin" data-pin-id="${p.id}"><input data-pin-field="no" value="${esc(p.no)}"><input data-pin-field="definition" value="${esc(p.definition)}"><input data-pin-field="function" value="${esc(p.function||'')}"></div>`).join('')}</div></details>`;}
  function deviceHtml(d){return`<div class="sch-device-row" data-device-id="${d.id}"><select data-device-field="type">${Object.entries(deviceTypes).map(([k,v])=>`<option value="${k}"${d.type===k?' selected':''}>${v}</option>`).join('')}</select><input data-device-field="name" value="${esc(d.name)}" placeholder="器件名称"><input data-device-field="value" value="${esc(d.value||'')}" placeholder="型号/参数"><input data-device-field="x" type="number" value="${esc(d.x)}" title="部件内X"><input data-device-field="y" type="number" value="${esc(d.y)}" title="部件内Y"><button data-delete-device="${d.id}" class="row-del">×</button></div>`;}
  const componentTypeRank=new Map(['component','container','external-hv','external-lv'].map((type,index)=>[type,index]));
  const deviceTypeRank=new Map(deviceCategories.flatMap(([,types])=>types).map((type,index)=>[type,index]));
  function stableGroup(items,rank,key){return items.map((item,index)=>({item,index})).sort((a,b)=>(rank.get(key(a.item))??999)-(rank.get(key(b.item))??999)||a.index-b.index).map(x=>x.item);}
  function workspaceOrdered(deviceGroup){
    const items=state.components.filter(c=>(c.type==='device')===deviceGroup),rank=deviceGroup?deviceTypeRank:componentTypeRank,key=deviceGroup?(c=>c.symbolType):(c=>c.type),known=items.filter(c=>Number.isFinite(c.workspaceOrder)).sort((a,b)=>a.workspaceOrder-b.workspaceOrder);let ordered;
    if(!known.length)ordered=stableGroup(items,rank,key);
    else{ordered=[...known];stableGroup(items.filter(c=>!Number.isFinite(c.workspaceOrder)),rank,key).forEach(item=>{let at=-1;for(let i=ordered.length-1;i>=0;i--)if(key(ordered[i])===key(item)){at=i+1;break;}if(at<0){const itemRank=rank.get(key(item))??999;at=ordered.findIndex(existing=>(rank.get(key(existing))??999)>itemRank);if(at<0)at=ordered.length;}ordered.splice(at,0,item);});}
    ordered.forEach((item,index)=>item.workspaceOrder=index);return ordered;
  }
