  function partComponentHtml(c,i){const opened=c.open===true||(c.open!==false&&i<2),minimum=componentMinimumSize(c);return`<details class="sch-component-editor" data-component-editor="${c.id}"${opened?' open':''}><summary><b>${workspaceDragHandle(c)}${i+1}. ${esc(c.name)}</b><span>${c.connectors.length} 个连接器 · ${c.devices.length} 个内嵌器件</span></summary><div class="sch-cmp-grid"><label>部件名称<input data-component-field="name" value="${esc(c.name)}"></label><label>类型<select data-component-field="type">${componentTypeOptions(c.type)}</select></label><label>X<input data-component-field="x" type="number" value="${c.x}"></label><label>Y<input data-component-field="y" type="number" value="${c.y}"></label><label>宽<input data-component-field="w" type="number" min="${minimum.w}" value="${c.w}"></label><label>高<input data-component-field="h" type="number" min="${minimum.h}" value="${c.h}"></label><button class="btn" data-clone-component="${c.id}">克隆部件</button><button class="btn danger" data-delete-component="${c.id}"${state.components.length===1?' disabled':''}>删除部件</button></div><div class="sch-subhead"><h5>连接器与Pin定义</h5><button class="btn" data-add-connector="${c.id}">＋连接器</button></div>${c.connectors.map(k=>connectorHtml(c,k)).join('')||'<p class="sch-empty">尚无连接器</p>'}<div class="sch-subhead"><h5>部件内器件</h5><button class="btn" data-add-device="${c.id}">＋器件</button></div><div class="sch-device-head"><b>符号</b><b>名称</b><b>型号/参数</b><b>X</b><b>Y</b><b></b></div>${groupedEmbeddedDevices(c.devices).map(deviceHtml).join('')||'<p class="sch-empty">尚无内嵌器件</p>'}</details>`;}
  function standaloneDeviceHtml(c,i){const opened=c.open===true,ground=c.symbolType==='ground';return`<details class="sch-component-editor sch-device-editor" data-component-editor="${c.id}"${opened?' open':''}><summary><b>${workspaceDragHandle(c)}${esc(deviceTypes[c.symbolType]||'器件')} · ${esc(c.name)}</b><span>${c.connectors.reduce((n,k)=>n+k.pins.length,0)} Pin</span></summary><div class="sch-cmp-grid sch-node-grid"><label>器件名称<input data-component-field="name" value="${esc(c.name)}"></label><label>图标<select data-component-field="symbolType">${Object.entries(deviceTypes).map(([k,v])=>`<option value="${k}"${k===c.symbolType?' selected':''}>${v}</option>`).join('')}</select></label><label>型号/参数<input data-component-field="value" value="${esc(c.value||'')}"></label><label>X<input data-component-field="x" type="number" value="${c.x}"></label><label>Y<input data-component-field="y" type="number" value="${c.y}"></label><button class="btn danger" data-delete-component="${c.id}">删除器件</button></div><div class="sch-subhead"><h5>器件Pin定义</h5><button class="btn" data-add-connector="${c.id}"${ground?' disabled':''}>＋Pin组</button></div>${c.connectors.map(k=>connectorHtml(c,k)).join('')||'<p class="sch-empty">尚无Pin</p>'}</details>`;}
